def validate_stress_accents(
    text: str, 
    allowed_exceptions: Optional[Set[str]] = None
) -> Tuple[bool, List[Dict[str, Any]]]:
    """
    Validates orthoepic stress accent markup (+) on multi-syllable Russian words.
    Rules:
    - Every multi-syllable Russian word (>1 vowel) must contain '+' preceding a vowel,
      unless it contains '\u0451' or is an allowed clitic/exception.
    - '+' must precede a vowel character.
    """
    exceptions = (allowed_exceptions or set()) | CLITICS
    violations: List[Dict[str, Any]] = []
    
    tokens = re.findall("[a-zA-Z\u0430-\u044f\u0451\u0410-\u042f\u04010-9+:\\-/$#|]+", text)
    
    for token in tokens:
        if not re.search("[\u0430-\u044f\u0451\u0410-\u042f\u0401]", token):
            continue
        clean = token.strip("-#|")
        vowels_in_token = [ch for ch in clean if ch in VOWELS]
        if len(vowels_in_token) <= 1:
            continue
        
        if "\u0451" in clean.lower():
            continue
            
        clean_lower = clean.replace("+", "").lower()
        if clean_lower in exceptions:
            continue
            
        if "+" not in clean:
            violations.append({
                "token": token,
                "reason": "Missing '+' stress accent on multi-syllable Russian word",
            })
        else:
            plus_matches = [m.start() for m in re.finditer(r"\+", clean)]
            valid_placement = all(
                (pos + 1 < len(clean) and clean[pos + 1] in VOWELS)
                for pos in plus_matches
            )
            if not valid_placement:
                violations.append({
                    "token": token,
                    "reason": "Stress '+' marker is not immediately preceding a vowel",
                })
                
    return (len(violations) == 0, violations)


def format_dsp_phonetics_ru(narration_text: str) -> str:
    """\u041f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u0443\u0435\u0442 \u0438\u043d\u0436\u0435\u043d\u0435\u0440\u043d\u044b\u0435 \u0430\u0431\u0431\u0440\u0435\u0432\u0438\u0430\u0442\u0443\u0440\u044b \u0438 \u0438\u043d\u0434\u0435\u043a\u0441\u044b \u043c\u0438\u043a\u0440\u043e\u0441\u0445\u0435\u043c \u0432 \u0444\u043e\u043d\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0444\u043e\u0440\u043c\u0443 \u0434\u043b\u044f TTS \u0441 \u043e\u0440\u0444\u043e\u044d\u043f\u0438\u0447\u0435\u0441\u043a\u0438\u043c\u0438 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u044f\u043c\u0438."""
    res = narration_text
    for token, spoken in DSP_PHONETIC_MAP:
        res = res.replace(token, spoken)
    res = re.sub(r"(\d+),(\d+)", "\\1 \u0438 \\2", res)
    return res


def stage_dsp_coursework_assets(output_dir: Path) -> Dict[str, Path]:
    """
    Stage and rasterize 300 DPI coursework assets (43-page PZ, ESKD drawings E2/PE2, and MATLAB figures)
    from DSP_COURSEWORK_DIR into output/dsp_assets/ for split-screen live inspector and interactive lightbox.
    """
    try:
        import fitz  # PyMuPDF
    except ImportError:
        fitz = None

    assets_dir = output_dir / "dsp_assets"
    assets_dir.mkdir(parents=True, exist_ok=True)
    staged: Dict[str, Path] = {}

    # 1. 43-Page Master Coursework PDF Rasterization at 300 DPI
    pz_pdf_name = (
        "\u041f\u043e\u044f\u0441\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f_"
        "\u0437\u0430\u043f\u0438\u0441\u043a\u0430_\u0426\u041e\u0421_\u0418\u0432\u0430\u043d\u043e\u0432.pdf"
    )
    pz_pdf_path = DSP_COURSEWORK_DIR / "coursework" / "release_final" / pz_pdf_name

    if pz_pdf_path.is_file() and fitz is not None:
        src_mtime = pz_pdf_path.stat().st_mtime
        needs_render = False
        for page_idx in range(43):
            dst_page = assets_dir / f"pz_page_{page_idx + 1:02d}.png"
            if not dst_page.is_file() or dst_page.stat().st_mtime < src_mtime or dst_page.stat().st_size == 0:
                needs_render = True
                break

        if needs_render:
            doc = fitz.open(str(pz_pdf_path))
            mat = fitz.Matrix(300.0 / 72.0, 300.0 / 72.0)
            for page_idx in range(min(43, len(doc))):
                dst_page = assets_dir / f"pz_page_{page_idx + 1:02d}.png"
                pix = doc[page_idx].get_pixmap(matrix=mat, alpha=False)
                pix.save(str(dst_page))
                staged[f"pz_page_{page_idx + 1:02d}"] = dst_page
                staged[f"pz_page_{page_idx + 1}"] = dst_page
            doc.close()
        else:
            for page_idx in range(43):
                dst_page = assets_dir / f"pz_page_{page_idx + 1:02d}.png"
                staged[f"pz_page_{page_idx + 1:02d}"] = dst_page
                staged[f"pz_page_{page_idx + 1}"] = dst_page
    else:
        for page_idx in range(43):
            dst_page = assets_dir / f"pz_page_{page_idx + 1:02d}.png"
            if dst_page.is_file():
                staged[f"pz_page_{page_idx + 1:02d}"] = dst_page
                staged[f"pz_page_{page_idx + 1}"] = dst_page
            else:
                from PIL import Image, ImageDraw
                dim = (4973, 3521) if page_idx == 41 else (2481, 3509)
                img = Image.new("RGB", dim, (16, 24, 42))
                draw = ImageDraw.Draw(img)
                draw.rectangle([(20, 20), (dim[0] - 20, dim[1] - 20)], outline=(56, 189, 248), width=4)
                draw.text((60, 280), f"Coursework PZ Page {page_idx + 1:02d}", fill=(226, 232, 240))
                img.save(dst_page)
                staged[f"pz_page_{page_idx + 1:02d}"] = dst_page
                staged[f"pz_page_{page_idx + 1}"] = dst_page

    # 2. ESKD Drawings E2 and PE2 Rasterization at 300 DPI
    drawing_sources = {
        "drawing_e2": (
            DSP_COURSEWORK_DIR / "coursework" / "drawings" / "\u041f\u0413\u0422\u0423.466225.001_\u042d2.pdf",
            (4973, 3521),
        ),
        "drawing_pe2": (
            DSP_COURSEWORK_DIR / "coursework" / "drawings" / "\u041f\u0413\u0422\u0423.466225.001_\u041f\u042d2.pdf",
            (2493, 3521),
        ),
    }

    for key, (pdf_src, fallback_size) in drawing_sources.items():
        dst_path = assets_dir / f"{key}.png"
        handled = False
        if pdf_src.is_file() and fitz is not None:
            src_mtime = pdf_src.stat().st_mtime
            if not dst_path.is_file() or dst_path.stat().st_mtime < src_mtime or dst_path.stat().st_size == 0:
                doc_drw = fitz.open(str(pdf_src))
                mat = fitz.Matrix(600.0 / 72.0, 600.0 / 72.0)
                pix = doc_drw[0].get_pixmap(matrix=mat, alpha=False)
                pix.save(str(dst_path))
                doc_drw.close()
            staged[key] = dst_path
            handled = True
        elif dst_path.is_file():
            staged[key] = dst_path
            handled = True

        if not handled:
            from PIL import Image, ImageDraw
            img = Image.new("RGB", fallback_size, (16, 24, 42))
            draw = ImageDraw.Draw(img)
            draw.rectangle([(20, 20), (fallback_size[0] - 20, fallback_size[1] - 20)], outline=(56, 189, 248), width=4)
            draw.text((60, 280), f"ESKD Drawing 300 DPI Asset: {key}", fill=(226, 232, 240))
            img.save(dst_path)
            staged[key] = dst_path

    # 3. Canonical MATLAB & Algorithm Figures
    figure_sources = {
        "fig_3_1": DSP_COURSEWORK_DIR / "pipeline" / "assets" / "fig_3_1_canonical.png",
        "fig_4_1": DSP_COURSEWORK_DIR / "pipeline" / "assets" / "fig_4_1_large.png",
        "fig_5_1": DSP_COURSEWORK_DIR / "pipeline" / "assets" / "fig_5_1_cropped.png",
        "fig_5_2": DSP_COURSEWORK_DIR / "pipeline" / "assets" / "fig_5_2_clean.png",
        "fig_5_3": DSP_COURSEWORK_DIR / "pipeline" / "assets" / "fig_5_3_clean.png",
        "fig_5_5": DSP_COURSEWORK_DIR / "pipeline" / "assets" / "fig_5_5_clean.png",
    }

    for key, src_path in figure_sources.items():
        dst_path = assets_dir / f"{key}.png"
        if src_path.is_file():
            if not dst_path.is_file() or dst_path.stat().st_mtime < src_path.stat().st_mtime or dst_path.stat().st_size != src_path.stat().st_size:
                shutil.copy2(src_path, dst_path)
            staged[key] = dst_path
        elif dst_path.is_file():
            staged[key] = dst_path
        else:
            from PIL import Image, ImageDraw
            img = Image.new("RGB", (3840, 2160), (16, 24, 42))
            draw = ImageDraw.Draw(img)
            draw.rectangle([(20, 20), (3820, 2140)], outline=(56, 189, 248), width=3)
            draw.text((60, 280), f"ESKD / MATLAB 300 DPI Asset: {key}", fill=(226, 232, 240))
            img.save(dst_path)
            staged[key] = dst_path

    return staged


