def _compute_scene_words_payload(narration_text: str, duration_sec: float) -> List[Dict[str, Any]]:
    clean_text = narration_text.replace("+", "").replace("*", "")
    tokens = clean_text.split()
    if not tokens:
        return []
    weights = []
    for tok in tokens:
        vowels = len(re.findall("[\u0430\u0435\u0451\u0438\u043e\u0443\u044b\u044d\u044e\u044faeiouy]", tok, re.IGNORECASE))
        is_acronym = bool(re.match(r"^[A-Z0-9_:-]{2,}", tok))
        w = max(1.5 * vowels, len(tok) * 0.4) if is_acronym else max(1.0, float(vowels))
        weights.append(w)
    total_w = sum(weights) or float(len(tokens))
    total_ms = float(duration_sec) * 1000.0
    start_margin = min(300.0, total_ms * 0.05)
    end_margin = min(300.0, total_ms * 0.05)
    voiced_ms = max(500.0, total_ms - start_margin - end_margin)
    words_data = []
    curr_ms = start_margin
    for tok, w in zip(tokens, weights):
        span_ms = (w / total_w) * voiced_ms
        words_data.append({
            "word": tok,
            "start_ms": round(curr_ms),
            "end_ms": round(curr_ms + span_ms),
        })
        curr_ms += span_ms
    return words_data


